INSERT INTO rabbi_page_items (rabbi_id,kind,series_id,lesson_id,sort_order) SELECT v.* FROM (VALUES ('00000000-0000-0000-0000-000000000000'::uuid,'series','00000000-0000-0000-0000-000000000000'::uuid,NULL::uuid,1)) AS v(rabbi_id,kind,series_id,lesson_id,sort_order) WHERE NOT EXISTS (SELECT 1 FROM rabbi_page_items r WHERE r.rabbi_id=v.rabbi_id AND r.kind=v.kind AND coalesce(r.series_id,r.lesson_id)=coalesce(v.series_id,v.lesson_id));
